"""API URL configuration — auto-generated by scanning actual view files."""
from django.urls import path, include
from rest_framework.routers import DefaultRouter
from . import views

router = DefaultRouter()
router.register(r'orders', views.OrderViewSet, basename='orders')
router.register(r'order-items', views.OrderItemViewSet, basename='order-items')
router.register(r'categories', views.CategoryViewSet, basename='categories')
router.register(r'menu-items', views.MenuItemViewSet, basename='menu-items')

urlpatterns = [
    # Explicit paths BEFORE router (router would swallow sub-paths like posts/feed/)


    # Auth endpoints (deterministic)
    path('auth/login/', views.CustomAuthToken.as_view(), name='auth-login'),
    path('auth/register/', views.RegisterView.as_view(), name='auth-register'),
    path('auth/logout/', views.LogoutView.as_view(), name='auth-logout'),
    path('auth/profile/', views.ProfileView.as_view(), name='auth-profile'),
    path('auth/user/', views.ProfileView.as_view(), name='auth-user'),
    path('auth/me/', views.ProfileView.as_view(), name='auth-me'),
    # Router URLs last — catch-all for ViewSet CRUD
    path('', include(router.urls)),
]
